/* ==================== BHY-BOT FAQ ENGINE ==================== */
(function () {
  var answers = [
    "Gampang banget! 1) Isi form order di halaman ini, 2) Bayar via QRIS / transfer, 3) Kirim bukti ke WhatsApp kami, dan akun langsung diproses! 🚀",
    "Super cepat! Setelah pembayaran dikonfirmasi, akun biasanya aktif dalam 5–30 menit. Kalau ada kendala, CS kami siap bantu 24 jam! ⚡",
    "Kami menerima QRIS (semua e-wallet & m-banking), Transfer Bank (BCA, BRI, Mandiri, BNI), dan GoPay / OVO / Dana! 💳",
    "100% aman! Setiap pembelian bergaransi. Kalau ada masalah dalam masa aktif, kami siap ganti atau refund. Kepercayaan kamu = prioritas kami! 🛡️",
    "Tergantung jenis akun ya! Sharing bisa 3–10 user, Private khusus kamu sendiri. Detail ada di deskripsi masing-masing paket! 📱",
    "Bisa! Hampir semua layanan streaming kami bisa diakses dari luar negeri. Untuk info spesifik per aplikasi, tanya CS kami dulu ya! 🌍",
    "Tentu! Kamu bisa perpanjang kapan saja sebelum masa aktif habis. Hubungi CS kami via WhatsApp untuk proses perpanjangan yang mudah! 🔄",
    "CS kami siap di WhatsApp 24/7! Klik tombol 'Chat WhatsApp' di halaman ini atau langsung hubungi 088272292088. Fast response! 📞",
  ];

  var canvas = document.getElementById("bhybotCanvas");
  if (!canvas) return;
  var ctx = canvas.getContext("2d");
  var W = canvas.width,
    H = canvas.height;
  var SCALE = 8;

  var frame = 0,
    step = 0,
    blinkTimer = 0,
    isBlinking = false,
    isWaving = false,
    waveTick = 0;
  var isHappy = false;

  // Color palette - bigger bot, cyan/purple theme
  var C = {
    body: "#0d0d2b",
    bodyL: "#1a1a4e",
    bodyD: "#070718",
    screen: "#00e5ff",
    screenD: "#0098aa",
    eye: "#ffffff",
    eyeP: "#7c5cfc",
    mouth: "#00e5ff",
    btn: "#7c5cfc",
    arm: "#0d0d2b",
    leg: "#0d0d2b",
    shoe: "#7c5cfc",
    antenna: "#00e5ff",
    glow: "rgba(0,229,255,0.18)",
    border: "#7c5cfc",
  };

  function px(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * SCALE, y * SCALE, SCALE, SCALE);
  }
  function pxRect(x, y, w, h, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * SCALE, y * SCALE, w * SCALE, h * SCALE);
  }

  function drawBot(waving) {
    ctx.clearRect(0, 0, W, H);

    var legOff = step % 2;

    // Glow bg
    ctx.fillStyle = C.glow;
    ctx.beginPath();
    ctx.ellipse(W / 2, H - 10, 50, 14, 0, 0, Math.PI * 2);
    ctx.fill();

    // Antenna
    px(9, 0, C.antenna);
    px(9, 1, C.antenna);
    px(8, 2, C.antenna);
    px(9, 2, C.antenna);
    px(10, 2, C.antenna);

    // HEAD
    pxRect(5, 3, 10, 9, C.bodyL);
    // Head border
    pxRect(5, 3, 10, 1, C.border);
    pxRect(5, 11, 10, 1, C.border);
    px(4, 4, C.border);
    px(4, 5, C.border);
    px(4, 6, C.border);
    px(4, 7, C.border);
    px(4, 8, C.border);
    px(4, 9, C.border);
    px(4, 10, C.border);
    px(15, 4, C.border);
    px(15, 5, C.border);
    px(15, 6, C.border);
    px(15, 7, C.border);
    px(15, 8, C.border);
    px(15, 9, C.border);
    px(15, 10, C.border);

    // Screen face
    pxRect(6, 4, 8, 7, C.screen);
    pxRect(7, 5, 6, 5, C.screenD);

    // Eyes
    if (!isBlinking) {
      pxRect(7, 5, 2, 2, C.eye);
      px(7, 5, C.eyeP);
      pxRect(11, 5, 2, 2, C.eye);
      px(11, 5, C.eyeP);
    } else {
      pxRect(7, 6, 2, 1, C.body);
      pxRect(11, 6, 2, 1, C.body);
    }

    // Mouth - smile if happy
    if (isHappy) {
      px(8, 8, C.mouth);
      px(9, 9, C.mouth);
      px(10, 9, C.mouth);
      px(11, 8, C.mouth);
    } else {
      px(8, 8, C.mouth);
      px(9, 8, C.mouth);
      px(10, 8, C.mouth);
      px(11, 8, C.mouth);
    }

    // NECK
    pxRect(8, 12, 4, 2, C.bodyD);

    // BODY
    pxRect(4, 14, 12, 9, C.body);
    pxRect(4, 14, 12, 1, C.border);
    pxRect(4, 22, 12, 1, C.border);
    px(3, 15, C.border);
    px(3, 16, C.border);
    px(3, 17, C.border);
    px(3, 18, C.border);
    px(3, 19, C.border);
    px(3, 20, C.border);
    px(3, 21, C.border);
    px(16, 15, C.border);
    px(16, 16, C.border);
    px(16, 17, C.border);
    px(16, 18, C.border);
    px(16, 19, C.border);
    px(16, 20, C.border);
    px(16, 21, C.border);

    // Chest detail
    pxRect(7, 16, 6, 3, C.bodyL);
    px(9, 17, C.antenna);
    px(10, 17, C.btn);

    // Side buttons
    px(17, 16, C.btn);
    px(17, 17, C.btn);
    px(17, 19, C.btn);
    px(17, 20, C.btn);

    // LEFT ARM - wave or down
    var lArmY = waving ? 4 : 15;
    pxRect(0, lArmY, 3, 7, C.arm);
    if (waving) {
      px(0, lArmY - 1, C.antenna);
      px(1, lArmY - 1, C.antenna);
    }

    // RIGHT ARM (always down)
    pxRect(17, 15, 3, 7, C.arm);

    // LEGS
    pxRect(5, 23, 4, 3, C.leg);
    pxRect(4, 25 + legOff, 5, 1, C.shoe);
    pxRect(11, 23, 4, 3, C.leg);
    pxRect(11, 25 + (1 - legOff), 5, 1, C.shoe);
  }

  // Animation loop
  function animLoop() {
    frame++;
    if (frame % 6 === 0) step = step === 0 ? 1 : 0;
    blinkTimer++;
    if (blinkTimer > 90 && !isBlinking) {
      isBlinking = true;
      blinkTimer = 0;
    }
    if (isBlinking && blinkTimer > 5) isBlinking = false;

    if (isWaving) {
      waveTick++;
      drawBot(waveTick % 10 < 5);
      if (waveTick > 30) {
        isWaving = false;
        waveTick = 0;
      }
    } else {
      drawBot(false);
    }
  }

  setInterval(animLoop, 100);
  drawBot(false);

  // Canvas click - wave + robot sound
  canvas.addEventListener("click", function () {
    isWaving = true;
    waveTick = 0;
    playRobotSound();
  });

  function playRobotSound() {
    var audioEl = document.getElementById("bhybotAudio");
    if (!audioEl) return;

    var AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) {
      audioEl.currentTime = 0;
      audioEl.play();
      return;
    }

    var actx = new AudioCtx();

    // Source dari elemen audio
    var source = actx.createMediaElementSource(audioEl);

    // 1. WAVESHAPER — distorsi robot (bitcrusher feel)
    var distortion = actx.createWaveShaper();
    (function makeDistCurve(amount) {
      var n = 256,
        curve = new Float32Array(n);
      for (var i = 0; i < n; i++) {
        var x = (i * 2) / n - 1;
        curve[i] = ((Math.PI + amount) * x) / (Math.PI + amount * Math.abs(x));
      }
      distortion.curve = curve;
      distortion.oversample = "4x";
    })(120);

    // 2. CONVOLVER — reverb buatan (impulse response sintetis)
    var convolver = actx.createConvolver();
    (function makeReverb() {
      var sampleRate = actx.sampleRate;
      var length = sampleRate * 1.8; // 1.8 detik reverb
      var impulse = actx.createBuffer(2, length, sampleRate);
      for (var ch = 0; ch < 2; ch++) {
        var data = impulse.getChannelData(ch);
        for (var i = 0; i < length; i++) {
          data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, 2.5);
        }
      }
      convolver.buffer = impulse;
    })();

    // 3. BIQUAD FILTER — potong frekuensi tengah, robot telephone feel
    var filter = actx.createBiquadFilter();
    filter.type = "bandpass";
    filter.frequency.value = 1400;
    filter.Q.value = 0.8;

    // 4. GAIN nodes — dry/wet mix
    var dryGain = actx.createGain();
    var wetGain = actx.createGain();
    var masterGain = actx.createGain();
    dryGain.gain.value = 0.4;
    wetGain.gain.value = 0.65;
    masterGain.gain.value = 1.1;

    // Routing: source → filter → distortion → dry + wet(reverb) → master → out
    source.connect(filter);
    filter.connect(distortion);
    distortion.connect(dryGain);
    distortion.connect(convolver);
    convolver.connect(wetGain);
    dryGain.connect(masterGain);
    wetGain.connect(masterGain);
    masterGain.connect(actx.destination);

    audioEl.currentTime = 0;
    audioEl.play();

    // Tutup context setelah audio selesai
    audioEl.onended = function () {
      setTimeout(function () {
        actx.close();
      }, 2000);
    };
  }

  // FAQ answers
  var answers_data = [
    "Gampang! 1) Isi form order, 2) Bayar via QRIS/transfer, 3) Kirim bukti ke WhatsApp. Akun langsung diproses! 🚀",
    "Setelah pembayaran dikonfirmasi, akun aktif dalam 5–30 menit. CS kami siap bantu 24 jam! ⚡",
    "Kami terima QRIS, Transfer Bank (BCA/BRI/Mandiri/BNI), GoPay, OVO, dan Dana! 💳",
    "100% aman & bergaransi! Ada masalah dalam masa aktif? Kami siap ganti atau refund! 🛡️",
    "Tergantung paket: Sharing 3–10 user, Private khusus kamu sendiri. Cek detail di katalog! 📱",
    "Bisa! Hampir semua layanan bisa diakses dari luar negeri. Tanya CS untuk info spesifik! 🌍",
    "Bisa perpanjang kapan saja! Hubungi CS via WhatsApp sebelum masa aktif habis. 🔄",
    "CS kami aktif 24/7 di WhatsApp! Klik tombol Chat atau hubungi 088272292088. 📞",
  ];

  var bubbleTxt = document.getElementById("bhybotText");
  var closeBtn = document.getElementById("bhybotClose");
  var bubble = document.getElementById("bhybotBubble");
  var faqBtns = document.querySelectorAll(".faq-btn");

  faqBtns.forEach(function (btn) {
    btn.addEventListener("click", function () {
      var q = parseInt(btn.getAttribute("data-q"));
      // Reset active
      faqBtns.forEach(function (b) {
        b.classList.remove("active");
      });
      btn.classList.add("active");
      // Answer
      bubbleTxt.innerHTML = answers_data[q];
      bubble.style.animation = "none";
      void bubble.offsetHeight;
      bubble.style.animation = "bubblePop 0.3s ease";
      // Bot reacts
      isHappy = true;
      isWaving = true;
      waveTick = 0;

      setTimeout(function () {
        isHappy = false;
      }, 3000);
    });
  });

  closeBtn.addEventListener("click", function () {
    faqBtns.forEach(function (b) {
      b.classList.remove("active");
    });
    bubbleTxt.innerHTML =
      "Saya <strong>Bhy-Bot</strong> akan menjawab pertanyaannya! 👾";
  });
})();
/* ==================== END BHY-BOT ==================== */

