// ===== CANVAS VIDEO (transparent bg – smooth) =====
(function () {
  const video = document.getElementById("heroVideo");
  const canvas = document.getElementById("heroCanvas");
  const logo = document.getElementById("heroLogoStatic");
  if (!video || !canvas) return;

  // Use OffscreenCanvas for pixel work when available (faster, no jank)
  const w = canvas.width,
    h = canvas.height;
  const ctx = canvas.getContext("2d", { willReadFrequently: true });

  let raf = null;
  let offscreen = null,
    offCtx = null;
  try {
    offscreen = new OffscreenCanvas(w, h);
    offCtx = offscreen.getContext("2d", { willReadFrequently: true });
  } catch (e) {}

  function drawFrame() {
    if (video.paused || video.ended) return;

    // Draw to offscreen (or main) canvas
    const c = offCtx || ctx;
    const cvs = offscreen || canvas;
    c.drawImage(video, 0, 0, w, h);

    const imageData = c.getImageData(0, 0, w, h);
    const d = imageData.data;
    const len = d.length;

    // Process every pixel – remove black background
    for (let i = 0; i < len; i += 4) {
      // Use max channel as brightness (fast, avoids multiply)
      const bright =
        d[i] > d[i + 1]
          ? d[i] > d[i + 2]
            ? d[i]
            : d[i + 2]
          : d[i + 1] > d[i + 2]
            ? d[i + 1]
            : d[i + 2];
      if (bright < 25) {
        d[i + 3] = 0;
      } else if (bright < 70) {
        d[i + 3] = (((bright - 25) / 45) * 255) | 0;
      }
      // bright >= 70: keep fully opaque (alpha stays 255)
    }

    if (offscreen) {
      // Put pixels back to offscreen, blit to main canvas
      offCtx.putImageData(imageData, 0, 0);
      ctx.clearRect(0, 0, w, h);
      ctx.drawImage(offscreen, 0, 0);
    } else {
      ctx.putImageData(imageData, 0, 0);
    }

    raf = requestAnimationFrame(drawFrame);
  }

  video.addEventListener("play", drawFrame);
  video.addEventListener("ended", () => {
    cancelAnimationFrame(raf);
    onHeroVideoEnd();
  });

  // Autoplay
  video.play().catch(() => {
    // Browser blocked autoplay – show static logo
    canvas.style.opacity = "0";
    logo.style.opacity = "1";
  });
})();

function onHeroVideoEnd() {
  const canvas = document.getElementById("heroCanvas");
  const logo = document.getElementById("heroLogoStatic");
  // Cross-fade: canvas out, logo in – both in the same grid cell so no movement
  canvas.style.opacity = "0";
  logo.style.opacity = "1";
}
